param([string]$TexturePath, [string]$SplashPak, [string]$VersionExe, [switch]$AutoTest, [string]$QuestPath, [string[]]$SourceRoots)

$ErrorActionPreference = 'Stop'

$embedded = @{
    'FireURQ-StreamSource-x86.bb744450ea6b4644af700bc15aebf245.ps1' = ''
    'FireURQ-D3D8TriangleOverlay.ps1' = ''
    'FireURQ-D3D8GeneratedSceneOverlay.ps1' = ''
    'FireURQ-D3D8RenderTextureOverlay.ps1' = ''
}

$workRoot = Join-Path (Split-Path -Parent $PSScriptRoot) '.fireurq-work'
$oldTextPane = $env:FIREURQ_PROBE_TEXT_PANE
$oldInteractive = $env:FIREURQ_PROBE_INTERACTIVE
$oldSysMenu = $env:FIREURQ_PROBE_SYSMENU
$oldSysButton = $env:FIREURQ_PROBE_SYSBUTTON
$oldInvButton = $env:FIREURQ_PROBE_INVBUTTON
$oldQuestLoader = $env:FIREURQ_PROBE_QUEST_LOADER
$oldQuestVerification = $env:FIREURQ_PROBE_VERIFICATION
$oldQuest = $env:FIREURQ_PROBE_QUEST
$oldMain = $env:FIREURQ_PROBE_MAIN
$oldVersion = $env:FIREURQ_PROBE_VERSION
$oldIconExe = $env:FIREURQ_PROBE_ICON_EXE
$oldQuestName = $env:FIREURQ_PROBE_QUEST_NAME
$oldMainBg = $env:FIREURQ_PROBE_MAIN_BG
$oldFont = $env:FIREURQ_PROBE_FONT
$oldQuestFont = $env:FIREURQ_PROBE_QUEST_FONT
$oldVColor = $env:FIREURQ_PROBE_VCOLOR
$oldSplashBg = $env:FIREURQ_PROBE_SPLASH_BG
$oldSplash = $env:FIREURQ_PROBE_SPLASH
$oldImagePath = $env:FIREURQ_PROBE_IMAGE
$oldTemp = $env:TEMP
$oldTmp = $env:TMP
$runDir = Join-Path $workRoot ('FireURQ.RenderTexture.' + [Guid]::NewGuid().ToString('N'))
Push-Location -LiteralPath (Split-Path -Parent $PSScriptRoot)

try {
    New-Item -ItemType Directory -Path $runDir -Force | Out-Null
    $env:FIREURQ_PROBE_IMAGE = if ($TexturePath) {
        (Get-Item -LiteralPath $TexturePath -ErrorAction Stop).FullName
    } else { $null }
    $env:FIREURQ_PROBE_SPLASH = $null
    $env:FIREURQ_PROBE_TEXT_PANE = $null
    $env:FIREURQ_PROBE_QUEST_FONT = $null
    $env:FIREURQ_PROBE_INTERACTIVE = if ($SplashPak -and !$AutoTest) { '1' } else { $null }
    $env:FIREURQ_PROBE_SYSMENU = $null
    $env:FIREURQ_PROBE_SYSBUTTON = $null
    $env:FIREURQ_PROBE_INVBUTTON = $null
    $env:FIREURQ_PROBE_QUEST = $null
    if ($QuestPath -and !$SplashPak) { throw '-QuestPath requires -SplashPak.' }
    $env:FIREURQ_PROBE_MAIN = $null
    $env:FIREURQ_PROBE_VERSION = $null
    $env:FIREURQ_PROBE_ICON_EXE = $null
    $env:FIREURQ_PROBE_QUEST_NAME = $null
    $env:FIREURQ_PROBE_MAIN_BG = 'FF000000'
    if ($VersionExe -and !$SplashPak) { throw '-VersionExe requires -SplashPak.' }
    if ($SplashPak) {
        if ($TexturePath) { throw 'Choose either -TexturePath or -SplashPak.' }
        Add-Type -AssemblyName System.IO.Compression.FileSystem
        $pakFile = Get-Item -LiteralPath $SplashPak
        if ($VersionExe) {
            $env:FIREURQ_PROBE_ICON_EXE = (Get-Item -LiteralPath $VersionExe).FullName
        } else {
            $iconExe = Get-ChildItem -LiteralPath $pakFile.DirectoryName -File -Filter 'fireurq*.exe' |
                Sort-Object Name | Select-Object -First 1
            if ($iconExe) { $env:FIREURQ_PROBE_ICON_EXE = $iconExe.FullName }
        }
        $pak = [IO.Compression.ZipFile]::OpenRead($pakFile.FullName)
        try {
            $splashBg = '00000000'
            $versionColor = 'FFEE9A00'
            $skinEntry = $pak.GetEntry('furq_default_skin.xml')
            if ($skinEntry) {
                $skinStream = $skinEntry.Open()
                try {
                    $skin = New-Object System.Xml.XmlDocument
                    $skin.XmlResolver = $null
                    # The original skin declares "window-1251". Decode its bytes
                    # before parsing so XmlDocument does not resolve that alias.
                    $reader = [IO.StreamReader]::new(
                        $skinStream, [Text.Encoding]::GetEncoding(1251), $true)
                    try {
                        $skin.LoadXml($reader.ReadToEnd())
                    } finally {
                        $reader.Dispose()
                    }
                    $mainNode = $skin.SelectSingleNode('/skin/main')
                    if ($mainNode -and $mainNode.HasAttribute('bgcolor')) {
                        $hex = $mainNode.GetAttribute('bgcolor').Trim() -replace '^(?:\$|0x)', ''
                        if ($hex -notmatch '^[0-9a-fA-F]{1,8}$') {
                            throw 'Invalid main background color in furq_default_skin.xml.'
                        }
                        $env:FIREURQ_PROBE_MAIN_BG = [Convert]::ToUInt32($hex, 16).ToString('X8')
                    }
                    $systemMenu = $skin.SelectSingleNode('/skin/main/menus/sysmenu')
                    if ($systemMenu -and $systemMenu.GetAttribute('datum') -eq 'lt') {
                        $menuX = [int]$systemMenu.GetAttribute('posx')
                        $menuY = [int]$systemMenu.GetAttribute('posy')
                        $env:FIREURQ_PROBE_SYSMENU = "$menuX,$menuY"
                    }
                    $systemButton = $skin.SelectSingleNode('/skin/main/menus/sysbutton')
                    if ($systemButton) {
                        $buttonBounds = @(foreach ($attribute in @('posx', 'posy', 'width', 'height')) {
                            [int]$systemButton.GetAttribute($attribute)
                        })
                        $env:FIREURQ_PROBE_SYSBUTTON = $buttonBounds -join ','
                    }
                    $inventoryButton = $skin.SelectSingleNode('/skin/main/menus/invbutton')
                    if ($inventoryButton) {
                        $inventoryBounds = @(foreach ($attribute in @('posx', 'posy', 'width', 'height')) {
                            [int]$inventoryButton.GetAttribute($attribute)
                        })
                        $env:FIREURQ_PROBE_INVBUTTON = $inventoryBounds -join ','
                    }
                    $screenNode = $skin.SelectSingleNode('/skin/screen')
                    $sprites = $skin.SelectNodes('/skin/main/menus/sysbutton | /skin/main/menus/invbutton | /skin/main/decorations/image')
                    if ($screenNode -and $sprites.Count -gt 0) {
                        $layout = @([int]$screenNode.GetAttribute('width'), [int]$screenNode.GetAttribute('height'))
                        if ($layout[0] -le 0 -or $layout[1] -le 0) { throw 'Invalid skin screen size.' }
                        foreach ($sprite in $sprites) {
                            $texture = $skin.SelectSingleNode('/skin/resources/texture[@name="res"]')
                            if ($sprite.GetAttribute('tex') -ne 'res' -or !$texture -or $texture.GetAttribute('file') -ne 'furq_texture.png') {
                                throw 'Main scene preview requires the stock res atlas.'
                            }
                            foreach ($attribute in @('tx', 'ty', 'width', 'height', 'posx', 'posy')) {
                                $layout += [int]$sprite.GetAttribute($attribute)
                            }
                        }
                        $env:FIREURQ_PROBE_MAIN = $layout -join ','
                        $textPane = $skin.SelectSingleNode('/skin/main/textpane')
                        if ($textPane) {
                            $bounds = @(foreach ($attribute in @('left', 'top', 'width', 'height')) {
                                [int]$textPane.GetAttribute($attribute)
                            })
                            if ($bounds[2] -lt 1 -or $bounds[2] -gt 2048 -or $bounds[3] -lt 1 -or $bounds[3] -gt 2048) {
                                throw 'Unsupported text pane size in this preview.'
                            }
                            $env:FIREURQ_PROBE_TEXT_PANE = $bounds -join ','
                        }
                    }
                    $node = $skin.SelectSingleNode('/skin/splash')
                    if ($VersionExe -and $node -and $node.HasAttribute('vcolor')) {
                        $hexColor = $node.GetAttribute('vcolor').Trim() -replace '^(?:\$|0x)', ''
                        if ($hexColor -notmatch '^[0-9a-fA-F]{1,8}$') { throw 'Invalid splash vcolor.' }
                        $versionColor = [Convert]::ToUInt32($hexColor, 16).ToString('X8')
                    }
                    if ($node -and $node.HasAttribute('bgcolor')) {
                        $hex = $node.GetAttribute('bgcolor').Trim() -replace '^(?:\$|0x)', ''
                        if ($hex -notmatch '^[0-9a-fA-F]{1,8}$') {
                            throw 'Invalid splash bgcolor in furq_default_skin.xml.'
                        }
                        $splashBg = [Convert]::ToUInt32($hex, 16).ToString('X8')
                    }
                } finally {
                    $skinStream.Dispose()
                }
            }
            $env:FIREURQ_PROBE_SPLASH_BG = $splashBg
            Write-Host "Splash background ARGB: $splashBg"
            $entry = $pak.GetEntry('furq_texture.png')
            if (!$entry) { throw 'furq_texture.png is missing from fireurq.pak.' }
            $atlas = Join-Path $runDir 'furq_texture.png'
            [IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $atlas)
            $env:FIREURQ_PROBE_IMAGE = $atlas
            if ($env:FIREURQ_PROBE_TEXT_PANE) {
                $questFontEntry = $pak.GetEntry('ptserif.ttf')
                if (!$questFontEntry) { throw 'ptserif.ttf is missing from fireurq.pak.' }
                $questFontPath = Join-Path $runDir 'ptserif.ttf'
                [IO.Compression.ZipFileExtensions]::ExtractToFile($questFontEntry, $questFontPath)
                $env:FIREURQ_PROBE_QUEST_FONT = $questFontPath
            }
            if ($VersionExe) {
                $exe = Get-Item -LiteralPath $VersionExe -ErrorAction Stop
                $version = [Diagnostics.FileVersionInfo]::GetVersionInfo($exe.FullName).ProductVersion
                if ([string]::IsNullOrWhiteSpace($version)) { throw 'ProductVersion was empty.' }
                $fontEntry = $pak.GetEntry('ptsans.ttf')
                if (!$fontEntry) { throw 'ptsans.ttf is missing from fireurq.pak.' }
                $fontPath = Join-Path $runDir 'ptsans.ttf'
                [IO.Compression.ZipFileExtensions]::ExtractToFile($fontEntry, $fontPath)
                $env:FIREURQ_PROBE_FONT = $fontPath
                $env:FIREURQ_PROBE_VCOLOR = $versionColor
                $env:FIREURQ_PROBE_VERSION = $version
            }
            $env:FIREURQ_PROBE_SPLASH = '1'
        } finally {
            $pak.Dispose()
        }
    }
    $env:TEMP = $runDir
    $env:TMP = $runDir
    Write-Host 'Generating fresh C# for the render texture probe...'
    $verificationParameters = @{ PreviousErrorCount = 71 }
    if ($PSBoundParameters.ContainsKey('SourceRoots')) {
        $verificationParameters.SourceRoots = $SourceRoots
    }
    $verification = @(& (Join-Path $PSScriptRoot 'VerifyGeneratedProject.ps1') @verificationParameters 6>&1 |
        ForEach-Object {
            Write-Host ([string]$_)
            [string]$_ -split '\r?\n'
        })

    $directoryLine = $verification |
        Where-Object { $_ -like 'Verification directory:*' } |
        Select-Object -First 1
    if (!$directoryLine) { throw 'Verification directory was not reported.' }

    $verificationDirectory = ($directoryLine -replace '^Verification directory:[ \t]*', '').Trim()
    if (!(Test-Path -LiteralPath $verificationDirectory -PathType Container)) {
        throw "Verification directory does not exist: [$verificationDirectory]"
    }
    $generated = Join-Path $verificationDirectory 'translation-output'
    $env:FIREURQ_PROBE_QUEST_LOADER = Join-Path $PSScriptRoot 'TestGeneratedQuestLoader.ps1'
    $env:FIREURQ_PROBE_VERIFICATION = $verificationDirectory
    if ($QuestPath) {
        $questXml = Join-Path $runDir 'quest.xml'
        & powershell.exe -NoProfile -File (Join-Path $PSScriptRoot 'TestGeneratedQuestLoader.ps1') -VerificationDirectory $verificationDirectory -QuestPath $QuestPath -ExportLocations $questXml
        if ($LASTEXITCODE -ne 0 -or !(Test-Path -LiteralPath $questXml -PathType Leaf)) {
            throw 'Generated quest loader did not export locations.'
        }
        $env:FIREURQ_PROBE_QUEST = $questXml
        $env:FIREURQ_PROBE_QUEST_NAME = [IO.Path]::GetFileName($QuestPath)
    }
    $core = Join-Path $generated 'd2dge-furq_2_2_4\d2dCore.cs'
    $runtime = Join-Path $generated '__runtime\D3D8Adapter.cs'
    foreach ($file in @($core, $runtime)) {
        if (!(Test-Path -LiteralPath $file -PathType Leaf)) {
            throw "Fresh generated file is missing: $file"
        }
    }


    foreach ($name in $embedded.Keys) {
        $path = Join-Path $runDir $name
        [IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($embedded[$name]))

        if ($name -like 'FireURQ-StreamSource-x86.*.ps1') { continue }

        $source = [IO.File]::ReadAllText($path)
        $source = [regex]::Replace($source, '(?m)^[ \t]*/\*[^\r\n]*\*/[ \t]*$', '')
        $source = $source.Replace('$env:TEMP', '$fireurqProbeDirectory')
        [IO.File]::WriteAllText($path, $source, [Text.UTF8Encoding]::new($true))
    }

    # The embedded overlays expect these two historical path names.
    # Supply both from the C# generated by this invocation.
    $aliases = @(
        'FireURQ.ProjectVerification.5ed6fb2af5a343b3b78f61b755f92588'
        'FireURQ.ProjectVerification.b686768659794ecba5e08346cfa036ff'
    )
    foreach ($alias in $aliases) {
        $output = Join-Path $runDir "$alias\translation-output"
        New-Item -ItemType Directory -Path (Join-Path $output '__runtime') -Force | Out-Null
        New-Item -ItemType Directory -Path (Join-Path $output 'd2dge-furq_2_2_4') -Force | Out-Null
        Copy-Item -LiteralPath $runtime -Destination (Join-Path $output '__runtime')
        Copy-Item -LiteralPath $core -Destination (Join-Path $output 'd2dge-furq_2_2_4')
        Copy-Item -LiteralPath (Join-Path $generated 'd2dge-furq_2_2_4\d2dTypes.cs') -Destination (Join-Path $output 'd2dge-furq_2_2_4')
    }

    $fireurqProbeDirectory = $runDir
    & (Join-Path $runDir 'FireURQ-D3D8RenderTextureOverlay.ps1')
}
catch {
    $report = "STOP: $($_.Exception.GetBaseException().Message)"
    Write-Output $report
    Set-Clipboard -Value $report -ErrorAction Stop
    Write-Host 'RESULT COPIED'
}
finally {
    $env:FIREURQ_PROBE_TEXT_PANE = $oldTextPane
    $env:FIREURQ_PROBE_INTERACTIVE = $oldInteractive
    $env:FIREURQ_PROBE_SYSMENU = $oldSysMenu
    $env:FIREURQ_PROBE_SYSBUTTON = $oldSysButton
    $env:FIREURQ_PROBE_INVBUTTON = $oldInvButton
    $env:FIREURQ_PROBE_QUEST_LOADER = $oldQuestLoader
    $env:FIREURQ_PROBE_VERIFICATION = $oldQuestVerification
    $env:FIREURQ_PROBE_QUEST = $oldQuest
    $env:FIREURQ_PROBE_MAIN = $oldMain
    $env:FIREURQ_PROBE_VERSION = $oldVersion
    $env:FIREURQ_PROBE_ICON_EXE = $oldIconExe
    $env:FIREURQ_PROBE_QUEST_NAME = $oldQuestName
    $env:FIREURQ_PROBE_MAIN_BG = $oldMainBg
    $env:FIREURQ_PROBE_FONT = $oldFont
    $env:FIREURQ_PROBE_QUEST_FONT = $oldQuestFont
    $env:FIREURQ_PROBE_VCOLOR = $oldVColor
    $env:FIREURQ_PROBE_SPLASH_BG = $oldSplashBg
    $env:FIREURQ_PROBE_SPLASH = $oldSplash
    $env:FIREURQ_PROBE_IMAGE = $oldImagePath
    $env:TEMP = $oldTemp
    $env:TMP = $oldTmp
    Pop-Location
    if (Test-Path -LiteralPath $runDir) {
        Remove-Item -LiteralPath $runDir -Recurse -Force
    }
}